CREATE INTERACTIVE TABLE t (id INT) CLUSTER BY (id) AS SELECT 1 AS id;

CREATE INTERACTIVE TABLE empty_t (id INT) CLUSTER BY (id);

CREATE INTERACTIVE TABLE timestamped_t (id INT) CLUSTER BY (id)
ROW_TIMESTAMP = TRUE;

CREATE OR REPLACE INTERACTIVE TABLE dynamic_t CLUSTER BY (id)
TARGET_LAG = '5 minutes' WAREHOUSE = wh AS SELECT id FROM source_table;

CREATE TABLE regular_t (id INT) CLUSTER BY (id) AS SELECT 1 AS id;
